insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('be2b1a04-af2b-4cf1-8245-60ecb4ba0918', 0, 'La frase encadena tres acciones después de «may»: manejar, reservar y cargar. Tras un verbo modal siempre va el infinitivo sin cambios, así que las tres tienen que ir en la misma forma.');

