insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('59514fcd-f4f2-4198-84d3-28c5248d76b1', 2, 'Un recorrido por dentro de un museo es un tour «around»: se camina alrededor, de sala en sala. «Against» significa contra y «above» encima, y ninguna describe un recorrido.');

