insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0d061cef-abba-4360-87ee-0ae04e3eed81', 1, '«Time» es incontable, así que solo funciona la palabra que acompaña a incontables. «Several» y «many» exigen un plural contable, como «several days» o «many hours».');

