insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('af5c1423-e242-4929-9fab-086dd80373cd', 0, 'La frase dice que trabajan entre semana y también los fines de semana: describe con qué frecuencia lo hacen. «Already» habla de algo que ya pasó y «early» de la hora, no de la frecuencia.');

