insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9cceee91-de55-4b33-93e5-fa666ef9e4e2', 2, 'Estar lejos de casa por días o meses es «away from home»: es la expresión fija para ausentarse. «Inside from home» y «over from home» no existen.');

