insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f695a30b-7390-4de5-9bd4-b4f1c5754b1c', 1, 'El sujeto del párrafo es «tour guides», que en inglés se retoma con «they». El reflexivo tiene que concordar con ese sujeto, no con «tú» ni con «nosotros».');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
