insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a71fdd64-409e-4cb2-ae80-5fdc82bb7155', 1, 'La segunda parte explica por qué les queda poco tiempo: trabajan muchas horas. Ese es un vínculo de causa. «So» introduciría la consecuencia, que aquí va al revés, y «or» ofrecería una alternativa.');

