insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a4fce3af-fb2b-4dae-b4e9-4660a0da0f07', 0, 'Después del verbo «is» hace falta un sustantivo o un gerundio que funcione como tal: conocer gente. El infinitivo suelto y la tercera persona no encajan en esa posición.');

