  array['directly', 'totally', 'exactly', 'especially'],
  'Los adverbios de grado (totally, completely, fully) van antes de adjetivos que admiten un máximo, como awake o full.', 'publicada', 'modelo', '0e3497a2707f5ce35ade5d94744c92b0';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9ac3b4a3-955b-4901-a052-97ee86b548f6', 1, 'Lo que se quiere decir es que los perros entraban al escáner completamente despiertos, sin sedación. Ese grado total lo da «totally»; las otras tres modifican precisión, momento o énfasis, no el grado de vigilia.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
