insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f6a1ead7-3414-47df-a280-dafc11a3fd9c', 0, 'La investigación busca averiguar algo que todavía no se sabe: cómo funciona el cerebro del perro. Recibir, aceptar o revisar suponen que la información ya existe y está en sus manos.');

