insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1f3cd2ac-0e66-4b4f-9646-c61f0cdbc85a', 3, 'Una máquina que entrega datos los proporciona. «Feed» es alimentar, «serve» servir a alguien y «afford» poder costear algo: ninguno se usa con información en este sentido.');

