  array['patterns', 'recipes', 'methods', 'arrangements'],
  '«Training methods» es la combinación habitual en textos científicos. Descarta lo que no acompañe a training.', 'publicada', 'modelo', 'ebf71865f55f5863df40984df670ba70';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2927659d-9942-4613-bf94-efeae3845092', 2, 'Un entrenamiento positivo es una forma de hacer las cosas, es decir, un método. Las recetas son de cocina, los patrones son formas que se repiten y los arreglos son acuerdos u organización.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '589d2e9e-0a19-42ab-8d8f-9894907a03a6', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'b265a34c-d4a0-4280-99c6-578623620179', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (19)?',
  array['whenever', 'whatever', 'wherever', 'whoever'],
  'La familia -ever se reparte por categoría: when → tiempo, what → cosa, where → lugar, who → persona.', 'publicada', 'modelo', '8225fb2962c906566d6953cada91d9d8';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('589d2e9e-0a19-42ab-8d8f-9894907a03a6', 0, 'Los perros podían salir del escáner en el momento en que quisieran: eso es tiempo. Las otras tres preguntan por cosa, lugar y persona, y ninguna encaja con la libertad de salir.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '2446ad23-4475-4650-bb77-9e91fe857db0', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'b265a34c-d4a0-4280-99c6-578623620179', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (20)?',
  array['approached', 'caught', 'rescued', 'stolen'],
  'Fíjate en la institución que aparece: una charity de perros sin hogar rescata, no captura.', 'publicada', 'modelo', '18229b744f199276dab8db14c1d588ce';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2446ad23-4475-4650-bb77-9e91fe857db0', 2, 'Una perra que viene de una fundación de animales sin hogar fue rescatada. Acercarse no es un verbo que se use así, y atraparla o robarla contradice el sentido de una fundación protectora.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c8163fbc-0a3d-49b0-bfa6-63c64d181855', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'b265a34c-d4a0-4280-99c6-578623620179', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (21)?',
  array['earning', 'affect', 'reward', 'wage'],
  'Después de «a great» hace falta un sustantivo. Descarta primero los verbos y quédate con lo que se pueda contar.', 'publicada', 'modelo', '7432c9c17a5ef547f0b862a3dba33051';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c8163fbc-0a3d-49b0-bfa6-63c64d181855', 2, 'Conseguir los primeros mapas de actividad cerebral después de meses de entrenamiento es una recompensa al esfuerzo. «Wage» es el sueldo de un trabajo y «affect» es un verbo, no un sustantivo que quepa aquí.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '4463b922-9693-4cd9-9361-92676e40df9f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'b265a34c-d4a0-4280-99c6-578623620179', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (22)?',
  array['solved', 'noticed', 'imagined', 'designed'],
  'Cuando el objeto del verbo es un hallazgo (a similarity, a pattern), el verbo suele ser notice, observe o find.', 'publicada', 'modelo', '999576b9b3d11749aac6748da7f955f9';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4463b922-9693-4cd9-9361-92676e40df9f', 1, 'En experimentos posteriores observaron un parecido que ya estaba ahí: lo notaron. Un parecido no se resuelve, no se imagina si es real ni se diseña.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '02f2a029-53c3-403a-8275-94ff7532ed75', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'b265a34c-d4a0-4280-99c6-578623620179', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (23)?',
  array['If', 'till', 'Unless', 'Although'],
  'Si las dos mitades de la frase se oponen, el conector es although, though o even though.', 'publicada', 'modelo', '6f19aae76c2b7198c95f9fed5eb16753';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('02f2a029-53c3-403a-8275-94ff7532ed75', 3, 'La frase admite una limitación y aun así defiende el valor de los datos: es un contraste. «If» y «Unless» plantean condiciones y «till» habla de hasta cuándo, no de oposición.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '85c10765-30c4-4612-8b74-07e5b84d8f50', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (24)?',
  array['took off', 'took part', 'took away', 'took place'],
  'Los phrasal verbs cambian por completo con la preposición. Aprende «take place» = ocurrir.', 'publicada', 'modelo', '04505917ef246191aa3d142bd8b00e2c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('85c10765-30c4-4612-8b74-07e5b84d8f50', 3, 'Un crimen ocurre en un lugar, y eso en inglés es «take place». Los otros tres verbos compuestos significan despegar, participar y llevarse algo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '79180a70-47f9-4c76-8124-d89b45f834ca', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (25)?',
  array['fact', 'order', 'time', 'case'],
  'Las expresiones con «in» son bloques fijos: in fact, in time, in case, in order to. No se traducen palabra por palabra.', 'publicada', 'modelo', '5981f1f15b997e9b068cb3d0b01ab425';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('79180a70-47f9-4c76-8124-d89b45f834ca', 0, '«In fact» introduce un dato que refuerza lo dicho antes, que es justo lo que hace la frase al añadir que aparece en muchas fotos. «In order» y «in case» tienen otros usos y «in time» significa a tiempo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '74fda749-c488-4be6-b741-554876fdc4e2', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (26)?',
  array['Within', 'Despite', 'Beneath', 'Towards'],
  'Despite introduce un obstáculo que no impidió la acción. Búscalo cuando la frase describa algo hecho a pesar del riesgo.', 'publicada', 'modelo', '3fd77e88d00bae832743cec97542dfea';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('74fda749-c488-4be6-b741-554876fdc4e2', 1, 'Ella siguió grabando pese a los disparos: hay una oposición entre el peligro y su conducta. «Within» es dentro de, «beneath» debajo y «towards» hacia, y ninguna marca contraste.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '931882f2-fa12-46c3-96ca-04def01a0606', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (27)?',
  array['retiring', 'touring', 'escaping', 'transferring'],
  'El contraste de la frase te dice qué hacía la gente: si ella se quedó, los demás se iban.', 'publicada', 'modelo', 'b14971ee68d7a7dddbd647e2ecd37437';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('931882f2-fa12-46c3-96ca-04def01a0606', 2, 'Frente a unos disparos, lo que hace la mayoría es huir, y eso contrasta con que ella se quedara grabando. Jubilarse, hacer turismo o trasladarse no describen una reacción ante un atentado.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'b712b18c-2063-4d28-ae0e-fd39df84f627', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (28)?',
  array['achieved', 'argued', 'requested', 'warned'],
  'La segunda mitad de la frase («but she never gave it») te dice que el FBI no lo consiguió: descarta achieved.', 'publicada', 'modelo', 'de8ee9dff5c03ae02f5219019b81ae11';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b712b18c-2063-4d28-ae0e-fd39df84f627', 2, 'El FBI pidió públicamente la película, y ella nunca se la entregó: pedir y no recibir encajan. Lograr contradice el final de la frase, y discutir o advertir no se construyen con un objeto así.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '460dd769-04a3-4a23-938d-be826a1e386e', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (29)?',
  array['all', 'last', 'first', 'least'],
  'Las cuatro son expresiones fijas con «at». Repásalas juntas: at last, at first, at least, at all.', 'publicada', 'modelo', '1fd086b68d379c68e2770e9814265ca1';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('460dd769-04a3-4a23-938d-be826a1e386e', 1, '«At last» significa por fin, y encaja con una llamada que llega siete años después del crimen. «At all», «at first» y «at least» significan en absoluto, al principio y al menos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'd67a4a63-12cb-450c-95ce-770a24386e5d', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (30)?',
  array['unlucky', 'unfamiliar', 'uncertain', 'unexpected'],
  'Fíjate en el salto temporal de la frase: siete años después, cualquier novedad es unexpected.', 'publicada', 'modelo', 'd4610ad56d28e63c64060659c2ad6903';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d67a4a63-12cb-450c-95ce-770a24386e5d', 3, 'Una llamada que llega de la nada, años después, es inesperada. Que sea de mala suerte, desconocida o incierta no describe la sorpresa de que aparezca de repente.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '173cf97a-85b3-40b0-9169-accf419429f5', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (31)?',
  array['defended', 'insisted', 'demanded', 'required'],
  'Después del verbo viene «that + frase». Comprueba cuál de los cuatro admite esa construcción con ese sentido.', 'publicada', 'modelo', '0fb2377593efc8cb192b47cf8e14399d';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('173cf97a-85b3-40b0-9169-accf419429f5', 1, 'Ella sostuvo con firmeza que era la mujer del pañuelo, aunque su relato tuviera vacíos: eso es insistir. Exigir y requerir piden que otro haga algo, y defender necesitaría un objeto distinto.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '9ada1e4c-e7a5-4b60-a2b7-af95cb65422e', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (32)?',
  array['suppose', 'replay', 'provide', 'arrange'],
  'Vuelve a la colocación que ya viste: provide information, provide details. Es la misma familia.', 'publicada', 'modelo', 'f696e06b1f13da1af739d52d3ef13871';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9ada1e4c-e7a5-4b60-a2b7-af95cb65422e', 2, 'Lo que no hizo fue dar más detalles, y dar información es «provide». Suponer, volver a reproducir y organizar no funcionan con «further details» en esta frase.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '44f94169-1837-42ee-bc3d-accf02e2d61a', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '9b63024a-703f-4563-910b-49b37e2b6f91', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (33)?',
  array['whatever', 'wherever', 'whether', 'whilst'],
  'La pista es «or not» al final: siempre va con whether, nunca con if en esta posición.', 'publicada', 'modelo', '43d5983c7ec98a54d77214685deccaa0';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('44f94169-1837-42ee-bc3d-accf02e2d61a', 2, 'La frase plantea dos posibilidades unidas por «or not», y eso pide «whether». Las de la familia -ever introducen otra clase de idea y «whilst» significa mientras.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '0216575e-3c1d-4a64-9bcb-8ba039be449a', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'bdc92eed-d783-4f6f-b0d9-7ee25e100952', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (6)?',
  array['any', 'every', 'all'],
  'Con nombres de continentes o países, la fórmula para abarcarlo todo es «all of».', 'publicada', 'modelo', '62e99e78f7660b0a6faa17a8e8ad266c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0216575e-3c1d-4a64-9bcb-8ba039be449a', 2, 'Europa es un todo, así que la expresión es «in all of Europe». «Any» aparece sobre todo en preguntas y negaciones, y «every» exige un sustantivo contable en singular detrás.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '2b32bd45-b434-4efd-ae43-26faf96c0634', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'bdc92eed-d783-4f6f-b0d9-7ee25e100952', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (7)?',
  array['visit', 'visited', 'visits'],
  'Cuando «is» va seguido de un verbo, revisa si el sujeto hace la acción o la recibe. Si la recibe, va en participio.', 'publicada', 'modelo', '9d7de04fb3e48738e994fbdf810f96d1';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2b32bd45-b434-4efd-ae43-26faf96c0634', 1, 'El sujeto es la ciudad, que recibe la acción: la gente la visita por sus canales y museos. Eso obliga a la forma de participio detrás de «is». El infinitivo y la tercera persona dejarían la frase sin construcción.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c08e2c04-2ec3-4569-ba55-61a9d2a4510f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'bdc92eed-d783-4f6f-b0d9-7ee25e100952', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (8)?',
  array['ever', 'so', 'also'],
  'Also añade información. Si la frase acumula cualidades, ese es el adverbio.', 'publicada', 'modelo', 'ab748178b6087eeb00e9057f7a4a151a';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c08e2c04-2ec3-4569-ba55-61a9d2a4510f', 2, 'La frase suma una cualidad más a las ya mencionadas: además es una ciudad amable. «Ever» significa alguna vez y «so» introduce consecuencia o intensidad, no adición.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '4a06f163-653a-4229-b7e3-08a2d1d36718', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'bdc92eed-d783-4f6f-b0d9-7ee25e100952', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (9)?',
  array['everything', 'everyone', 'nothing'],
  'Mira lo que viene después del hueco: si es una lista de cosas, la respuesta es everything.', 'publicada', 'modelo', 'aba363c2be49ce6cacfbf4c690fc02f5';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4a06f163-653a-4229-b7e3-08a2d1d36718', 0, 'Enseguida se enumeran discotecas, restaurantes y transporte: la ciudad tiene todo lo que se encuentra en una gran ciudad. «Everyone» se refiere a personas y «nothing» diría lo contrario.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '9901d01f-9fd3-4777-b871-f554ce7eac35', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'bdc92eed-d783-4f6f-b0d9-7ee25e100952', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (10)?',
  array['for', 'after', 'out'],
  'Los phrasal verbs con look son tres muy distintos. Repásalos juntos: look for, look after, look out.', 'publicada', 'modelo', '7bc361c27e6bad9b6df3293ab23aeda6';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9901d01f-9fd3-4777-b871-f554ce7eac35', 0, '«Look for» es buscar, que es lo que hace quien quiere experiencias locales. «Look after» es cuidar y «look out» es tener cuidado: los tres cambian por completo con la preposición.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'f741615c-f5c1-42a2-a374-2ca63616c90f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'bdc92eed-d783-4f6f-b0d9-7ee25e100952', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (11)?',
  array['traveling', 'travel', 'travels'],
  'La partícula «to» de un infinitivo pide el verbo limpio, sin -ing ni -s.', 'publicada', 'modelo', '97fdc565b4b26642c41acd4756d763b6';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f741615c-f5c1-42a2-a374-2ca63616c90f', 1, 'Detrás de «a way to» siempre va el infinitivo sin cambios. El gerundio y la tercera persona romperían esa estructura.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '6ebbfe25-e6c2-48ea-ba0c-77678da9926c', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'bdc92eed-d783-4f6f-b0d9-7ee25e100952', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (12)?',
  array['than', 'while', 'if'],
  'Si la segunda parte de la frase es un consejo o una consecuencia, la primera suele abrirse con if.', 'publicada', 'modelo', '686b90dc2ef8a664c0237051552a32d3';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6ebbfe25-e6c2-48ea-ba0c-77678da9926c', 2, 'La frase pone una condición: si te quedas más tiempo, considera una excursión. «Than» sirve para comparar y «while» para hablar de simultaneidad.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'd28a274e-a590-4264-aee0-930293197991', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'bdc92eed-d783-4f6f-b0d9-7ee25e100952', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (13)?',
  array['each', 'both', 'other'],
  'Each se usa para uno por uno dentro de un grupo de más de dos; both solo cuando son exactamente dos.', 'publicada', 'modelo', 'bfdf9dfd4ad93b93a34ae5b7ea77df9b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d28a274e-a590-4264-aee0-930293197991', 0, 'Se acaba de hablar de varios pueblos y aldeas, y la frase dice que cada uno está lleno de cosas asombrosas. «Both» sirve solo para dos y «other one» necesitaría un artículo delante.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'f215fb72-b3af-441c-a353-97d39dde6a3e', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (16)?',
  array['pass', 'remove', 'take', 'fall'],
  'La estructura es «to + verbo + objeto». Busca el verbo que signifique eliminar por sí solo.', 'publicada', 'modelo', '487629fb0fab8ea1239636caee4063b0';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f215fb72-b3af-441c-a353-97d39dde6a3e', 1, 'El baño de polvo sirve para quitar la piel vieja, y quitar algo de encima es «remove». «Pass», «take» y «fall» no expresan esa eliminación sin una preposición que aquí no aparece.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '08a68567-097b-4a0e-90d4-14927af3c04c', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (17)?',
  array['off', 'along', 'up', 'between'],
  'Cuando algo queda atrapado en el hueco que separa dos partes, la preposición es between.', 'publicada', 'modelo', '609612ec17a7e5e3346b4cf9ae8c0ba5';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('08a68567-097b-4a0e-90d4-14927af3c04c', 3, 'Las piedras se atascan en el espacio que queda entre los dedos, y ese espacio entre varios elementos es «between». Las otras tres indican separación, recorrido y dirección hacia arriba.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'dc61639d-3002-4dfa-a860-3db714585c4e', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (18)?',
  array['scene', 'role', 'part', 'piece'],
  'Guárdala completa: «that&rsquo;s the easy part» anuncia que ahora viene lo difícil.', 'publicada', 'modelo', '72a3870f2fb3db543f77c362e940b553';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('dc61639d-3002-4dfa-a860-3db714585c4e', 2, '«That&rsquo;s the easy part» es la expresión hecha para decir que eso era lo fácil, frente a lo que viene después. Escena, papel y pieza no se usan así.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'e116a869-c422-44b7-b99a-1baa037c7b1e', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (19)?',
  array['now', 'before', 'once', 'then'],
  'Once, colocado antes del verbo en pasado, significa «en cierta ocasión», no «una vez» de conteo.', 'publicada', 'modelo', '0d556d42b933db9afc4f53fdccd395df';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e116a869-c422-44b7-b99a-1baa037c7b1e', 2, 'Se cita algo que el dueño del zoológico dijo en alguna ocasión del pasado, y ese «alguna vez» es «once». «Now» contradice el pasado del verbo, y «before» y «then» necesitarían un momento de referencia que la frase no da.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c299ff19-20e2-413e-beda-5656288df316', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (20)?',
  array['searches', 'needs', 'asks', 'keeps'],
  'Desarrolla la metáfora: ¿qué relación tiene un fuego con el combustible? Esa es la respuesta.', 'publicada', 'modelo', '5d95e2dd4b706bc7f9eff6b2210cc147';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c299ff19-20e2-413e-beda-5656288df316', 1, 'La comparación es con un fuego enorme, y lo que un fuego requiere para seguir ardiendo es combustible. Buscar, pedir y guardar no describen lo que un fuego hace con el combustible.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '6f933470-cd73-4f26-acdc-c236222d0800', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (21)?',
  array['when', 'whether', 'while', 'why'],
  'La fórmula «This is why…» encadena una causa con su efecto. Apréndela junto a «that&rsquo;s why».', 'publicada', 'modelo', '62d744edb2491e7d996379dd1d87a5bd';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6f933470-cd73-4f26-acdc-c236222d0800', 3, 'La frase anterior explica cuánto combustible necesita el elefante, y esta saca la consecuencia: por eso comen todo el día. «This is why» presenta la razón de lo que sigue.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'eb95082b-eb6f-4c32-8228-17a75b1fa044', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (22)?',
  array['continue', 'spend', 'give', 'stay'],
  'Spend sirve para tiempo y para dinero: spend time, spend money. Es la misma estructura.', 'publicada', 'modelo', '224ef1761c6159a36586cb556940b965';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('eb95082b-eb6f-4c32-8228-17a75b1fa044', 1, 'Dedicar tiempo a algo es «spend time», igual que se gasta dinero. Los otros tres verbos no admiten «time» como objeto directo en esta construcción.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '88e32db1-dc92-45bd-906f-6e37c277565e', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (23)?',
  array['totals', 'weights', 'numbers', 'quantities'],
  'Con alimentos incontables se usa quantities o amounts; numbers solo con cosas que se cuentan una a una.', 'publicada', 'modelo', '6f48d09ed2944eaec12e01fb857547f0';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('88e32db1-dc92-45bd-906f-6e37c277565e', 3, 'Verduras y fruta se miden como masa, no de una en una, así que se habla de grandes cantidades. «Numbers» exigiría contar unidades y «totals» y «weights» son resultados de una medición, no la medida misma.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '304c62ae-647f-4f2f-9b75-fe5c7006221f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (24)?',
  array['costs', 'buys', 'pays', 'charges'],
  'Reconoce el molde: It costs + dinero + to + verbo. Aparece siempre que se informa un precio.', 'publicada', 'modelo', '7aead13ec61bca6d7f0ba8ff6e10ebc3';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('304c62ae-647f-4f2f-9b75-fe5c7006221f', 0, 'La estructura «It costs… to do something» dice cuánto vale hacer algo. Comprar, pagar y cobrar necesitan a alguien que realice la acción, y aquí el sujeto es el impersonal «it».');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'b14ceee8-274f-4958-819c-f9996a65f0e6', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'c6d5c1a1-d8dd-4351-a9fe-67f6a1769529', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (25)?',
  array['purpose', 'idea', 'opinion', 'thought'],
  'A good idea / a bad idea es una pareja fija. Memorízala tal cual.', 'publicada', 'modelo', 'b14f7b3f4bb8c0677a93bc3d540ff273';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b14ceee8-274f-4958-819c-f9996a65f0e6', 1, '«It isn&rsquo;t a good idea» es la forma habitual de decir que algo es imprudente. Propósito, opinión y pensamiento no se combinan con «a good» en ese sentido de advertencia.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '4adb875c-9dc6-47d9-bab3-9ccd515a7423', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '8723fd91-7d80-41ef-86c5-a7132ce8bdc8', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (26)?',
  array['happier', 'happy', 'happiest'],
  'La presencia de «than» decide sola: si aparece, el adjetivo va en comparativo.', 'publicada', 'modelo', '8825c89542295cbf6d071b1c5e86d8d1';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4adb875c-9dc6-47d9-bab3-9ccd515a7423', 0, 'La palabra «than» al final obliga a una comparación entre dos situaciones: el parque y el circo. El adjetivo simple y el superlativo no admiten «than» detrás.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '47b17946-fdc5-4e47-9fea-7b228a315470', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '8723fd91-7d80-41ef-86c5-a7132ce8bdc8', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (27)?',
  array['thinking', 'thought', 'think'],
  'Una expresión de tiempo pasado al inicio marca el tiempo verbal de toda la oración.', 'publicada', 'modelo', '2064c4a8cbddaa710ff15ad678255651';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('47b17946-fdc5-4e47-9fea-7b228a315470', 1, 'La frase empieza con «One hundred years ago», así que todo el verbo va en pasado. El gerundio necesitaría un auxiliar delante y el presente contradice la fecha.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '4fadc364-e149-43fc-90f7-f7bff23f9e8e', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '8723fd91-7d80-41ef-86c5-a7132ce8bdc8', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (28)?',
  array['instead', 'next', 'however'],
  'However marca contraste entre dos épocas o dos ideas. Ubica siempre las dos mitades antes de escoger.', 'publicada', 'modelo', '5eead9e4821badeb508fa7f99799df58';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('4fadc364-e149-43fc-90f7-f7bff23f9e8e', 2, 'Antes se dice que hace cien años parecía aceptable y después que hoy las cosas cambiaron: eso es una oposición. «Instead» sustituye una cosa por otra y «next» ordena una secuencia.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '56d24703-7e55-43d8-acf4-36d59118ac6b', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '8723fd91-7d80-41ef-86c5-a7132ce8bdc8', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (29)?',
  array['begin', 'begun', 'began'],
  'Begin, began, begun: el tercero es el que acompaña a have o has.', 'publicada', 'modelo', '3a74e2122a83cbc196bebde2f728681d';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('56d24703-7e55-43d8-acf4-36d59118ac6b', 1, 'El auxiliar «have» pide el participio del verbo. «Began» es el pasado simple, que va solo, y «begin» es el infinitivo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'cd328ec5-0124-4265-bdc2-b1f39fa01d19', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '8723fd91-7d80-41ef-86c5-a7132ce8bdc8', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (30)?',
  array['for', 'about', 'of'],
  'Kind, type y sort van siempre con «of». Es una de las combinaciones más constantes del inglés.', 'publicada', 'modelo', 'b1c16ad469b74019b1d6ca4e9cbc4dc0';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('cd328ec5-0124-4265-bdc2-b1f39fa01d19', 2, '«Kinds of» es la fórmula fija para decir tipos de algo, igual que «types of» o «sorts of». Las otras dos preposiciones no se combinan con kinds.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '110ebd35-2489-4b3d-882c-098ef0c89681', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '8723fd91-7d80-41ef-86c5-a7132ce8bdc8', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (31)?',
  array['may', 'shall', 'should'],
  'May expresa posibilidad; should, consejo; shall, propuesta. Decide primero qué idea necesita la frase.', 'publicada', 'modelo', '8ed449cbd2dd957bb2e23ecb7a830454';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('110ebd35-2489-4b3d-882c-098ef0c89681', 0, 'Se habla de algo que puede llegar a pasarles a los elefantes del circo: es una posibilidad. «Shall» sirve para ofrecimientos y propuestas, y «should» daría un consejo, que no tiene sentido aquí.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '61cad0a6-4138-4dc4-8bfd-b8be1911324e', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '8723fd91-7d80-41ef-86c5-a7132ce8bdc8', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (32)?',
  array['else', 'just', 'almost'],
  'Just antes del verbo reduce la acción a lo mínimo: «solo quiere», nada más.', 'publicada', 'modelo', '2e9eca07c88098ccc4532cc93b337278';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('61cad0a6-4138-4dc4-8bfd-b8be1911324e', 1, 'El grupo quiere una sola cosa: que los elefantes descansen. «Just» limita la petición a eso. «Else» significa más o distinto y necesitaría otra palabra delante, y «almost» dejaría el deseo a medias.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '884bbb0e-0e02-4b5d-b19c-6cd3d95d29e4', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '8723fd91-7d80-41ef-86c5-a7132ce8bdc8', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (33)?',
  array['never', 'usually', 'always'],
  'La causa que cierra la frase («because people agree it is important to protect them») decide el adverbio.', 'publicada', 'modelo', 'a618a5959dbe468528337da7c7ed4ba7';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('884bbb0e-0e02-4b5d-b19c-6cd3d95d29e4', 0, 'La frase explica que en esos lugares la gente considera importante proteger a los elefantes, así que allí los espectáculos no los usan nunca. «Usually» y «always» dirían que sí los usan.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '46171897-3ba5-402e-b836-52994631fe09', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '65e1b7f6-818d-4674-a3e4-b160675030c0', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (23)?',
  array['begins', 'began', 'begun'],
  'Sin auxiliar y con fecha pasada, siempre pasado simple. Con have delante, participio.', 'publicada', 'modelo', 'a07bccf9439eadd9a4e8fa8740998e38';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('46171897-3ba5-402e-b836-52994631fe09', 1, 'La fecha «By 1982» sitúa la acción en el pasado y no hay ningún auxiliar delante, así que corresponde el pasado simple. «Begun» solo aparece con have o has.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'b8e622f0-6ff0-4a07-aaac-b65d263f3ca1', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '65e1b7f6-818d-4674-a3e4-b160675030c0', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (24)?',
  array['shall', 'will', 'must'],
  'En el primer condicional la fórmula es: if + presente, … will + verbo.', 'publicada', 'modelo', 'c201b3e3cd6b72802c9e7a64347e734b';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b8e622f0-6ff0-4a07-aaac-b65d263f3ca1', 1, 'Es una condición con su resultado probable: si escuchan a Mozart, se volverán más inteligentes. Ese resultado futuro lo marca «will». «Must» expresaría obligación y «shall» una propuesta.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'f77fa17e-d872-4e57-b2f4-0cafb73fc547', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '65e1b7f6-818d-4674-a3e4-b160675030c0', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (25)?',
  array['every', 'both', 'all'],
  'Revisa si el sustantivo está en singular o plural: every kind, pero all kinds.', 'publicada', 'modelo', '3b724243ba260b4f7cf1da5c99d43521';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f77fa17e-d872-4e57-b2f4-0cafb73fc547', 2, '«Kinds» está en plural, así que la palabra que lo acompaña debe admitir plural. «Every» exige singular y «both» se limita a dos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '3af0bf6e-e6ff-49a1-9228-c90676a8bc53', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '65e1b7f6-818d-4674-a3e4-b160675030c0', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (26)?',
  array['helping', 'helped', 'help'],
  'Cada vez que veas «to» antes del hueco, escribe el verbo en su forma base.', 'publicada', 'modelo', '4e8e179cc527c1a426e36491923542a0';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3af0bf6e-e6ff-49a1-9228-c90676a8bc53', 2, 'Detrás de «to» va el infinitivo sin marcas. El gerundio y el pasado no caben después de esa partícula.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '2ff7ca96-bc20-4956-a666-523d05d1592f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '65e1b7f6-818d-4674-a3e4-b160675030c0', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (27)?',
  array['also', 'once', 'yet'],
  'Also entre el modal y el verbo (can also reduce) es la posición típica para sumar una idea.', 'publicada', 'modelo', '4f5f51f11bf664c35c1ccc8fc5f098a4';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('2ff7ca96-bc20-4956-a666-523d05d1592f', 0, 'La frase añade un efecto más de la música, junto al de relajar: reducir el estrés. «Once» habla de una ocasión y «yet» de algo que todavía no ocurre.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'f50ceba0-4a6f-4e61-81a4-8b5e2fd2504e', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '65e1b7f6-818d-4674-a3e4-b160675030c0', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (28)?',
  array['been', 'being', 'be'],
  'Preposición + verbo = verbo en -ing. Vale para of, about, by, without y todas las demás.', 'publicada', 'modelo', '604e6237b4150c07adb2ffe4745e7af8';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('f50ceba0-4a6f-4e61-81a4-8b5e2fd2504e', 1, 'Después de la preposición «of» siempre va un gerundio. El infinitivo y el participio dejarían la frase incompleta.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'da0d7b67-a3aa-4417-9a97-78ad3f83ac91', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '65e1b7f6-818d-4674-a3e4-b160675030c0', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (29)?',
  array['planned', 'planning', 'plans'],
  'Cuando el hueco va después de is o it&rsquo;s y debe describir algo, prueba con la forma en -ed.', 'publicada', 'modelo', 'e8a58403ba4b11ed78b98f211aa042f3';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('da0d7b67-a3aa-4417-9a97-78ad3f83ac91', 0, 'Detrás de «it&rsquo;s» hace falta algo que describa la música, y la única de las tres que funciona como adjetivo es el participio: una música construida con orden. El gerundio y el plural no describen.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'a741c580-ac92-4c77-9d71-4f2a1684b397', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '65e1b7f6-818d-4674-a3e4-b160675030c0', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (30)?',
  array['highest', 'high', 'higher'],
  'Igual que en el texto del circo: si ves than, va comparativo. Es la regla más rentable de esta sección.', 'publicada', 'modelo', '269081df1e4419888b36fb9329650cda';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a741c580-ac92-4c77-9d71-4f2a1684b397', 2, 'La palabra «than» al final de la frase compara a dos grupos de estudiantes, así que el adjetivo va en comparativo. El superlativo no admite «than» y el adjetivo simple no compara.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '6866d481-48af-4b7c-aab8-5db1a3e733a2', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (26)?',
  array['time', 'fact', 'order', 'advance'],
  'In fact refuerza; in time significa a tiempo; in order to, para; in advance, por anticipado.', 'publicada', 'modelo', 'fd478ade648a61df61e8094d4594d151';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('6866d481-48af-4b7c-aab8-5db1a3e733a2', 1, '«In fact» confirma y precisa lo que se acaba de insinuar, que es exactamente lo que hace la frase al dar la cifra de 6.000 años. Las otras tres expresiones con «in» tienen usos distintos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '1056bcc1-735c-4ea4-bb74-583d62f58dac', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (27)?',
  array['diet', 'recipe', 'meal', 'ingredient'],
  '«The human diet» nombra la alimentación de una especie entera. Piensa en escala antes de escoger.', 'publicada', 'modelo', 'eb22a804b903fd38f5378621b9d1980c';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1056bcc1-735c-4ea4-bb74-583d62f58dac', 0, 'Formar parte de lo que la humanidad come durante milenios es formar parte de su alimentación. Una receta y una comida son casos puntuales, y un ingrediente iría con «an», no con «the human».');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c77b2a31-0786-4ad2-98c1-c9ed7f8b869b', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (28)?',
  array['delivered', 'explored', 'produced', 'discovered'],
  'La palabra «accidentally» delante del hueco te dice que fue un hallazgo, no una acción planeada.', 'publicada', 'modelo', 'c53b27c59f2d0531b9996a7a21dd2439';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c77b2a31-0786-4ad2-98c1-c9ed7f8b869b', 3, 'Colón se topó con el ají sin buscarlo y lo llevó a Europa: lo descubrió. Entregar, explorar y producir no describen ese encuentro casual con algo que ya existía.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '916253d7-9d05-437c-b235-649bc5024b4d', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (29)?',
  array['reasons', 'services', 'uses', 'values'],
  'Cuando el objeto es un producto, «different uses» es la colocación esperada.', 'publicada', 'modelo', '0abb764b01b4dae9940c009a723dac94';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('916253d7-9d05-437c-b235-649bc5024b4d', 2, 'Los europeos fueron encontrando distintas maneras de emplear la especia, y esas maneras son «uses». Razones, servicios y valores no se combinan con una especia en este sentido.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '19360f02-a102-44cd-8932-b80936510030', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (30)?',
  array['did', 'was', 'have', 'can'],
  'Modal + have + participio es el molde para el pasado de los modales: could have, should have, might have.', 'publicada', 'modelo', '8dfb73c717c42168268b50c83d9a0058';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('19360f02-a102-44cd-8932-b80936510030', 2, 'La estructura completa es «could never have imagined»: un modal seguido de have y participio para hablar de algo que no pudo pasar en el pasado. Los otros tres auxiliares no encajan detrás de «could».');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'd3e2f394-4826-45a3-beb4-6a05af5b0d65', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (31)?',
  array['down', 'off', 'for', 'into'],
  'Otra familia de phrasal verbs que conviene repasar junta: turn into, turn down, turn off, turn up.', 'publicada', 'modelo', '21ea6112c36d474cd3b9488678de5243';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d3e2f394-4826-45a3-beb4-6a05af5b0d65', 3, '«Turn into» es convertirse en algo distinto, que es lo que pasó con el ají al volverse la reina de las especias. «Turn down» es rechazar y «turn off» apagar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '3a1a20df-aadd-44d2-82c5-9c36db4818fc', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (32)?',
  array['favors', 'benefits', 'developments', 'improvements'],
  'Lee lo que viene después del punto y coma: si es una lista de efectos positivos, el sustantivo es benefits.', 'publicada', 'modelo', '6f24f1c697d45cdbd579dc8d2a8dc320';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('3a1a20df-aadd-44d2-82c5-9c36db4818fc', 1, 'Enseguida se enumeran efectos buenos para la salud: bajar el colesterol, frenar infecciones, combatir enfermedades óseas. Todo eso son beneficios. Los favores son entre personas y los avances o mejoras se refieren a procesos.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '95afd1b1-ba10-45e1-a89b-a4bb3c36a092', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (33)?',
  array['hide', 'defend', 'prevent', 'protect'],
  'Prevent va directo al problema que se evita; protect siempre pide «protect someone from something».', 'publicada', 'modelo', '25d31b6734d6ed082c774d0a1aca2bb5';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('95afd1b1-ba10-45e1-a89b-a4bb3c36a092', 2, 'Evitar que una infección aparezca es «prevent». «Protect» necesitaría decir de qué protege, con «from», y esconder o defender no se usan con infecciones.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '68e42b8f-1ded-443f-92c3-3daa147d45d8', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (34)?',
  array['Beyond', 'Upon', 'Despite', 'Beneath'],
  'Es el mismo despite del texto de la mujer del pañuelo. Cuando hay una advertencia pese a lo bueno, ese es el conector.', 'publicada', 'modelo', '5c8d706058cab9576332e771dfc19f32';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('68e42b8f-1ded-443f-92c3-3daa147d45d8', 2, 'La frase reconoce las ventajas y aun así advierte que no conviene abusar: es un contraste. «Beyond» es más allá, «upon» sobre y «beneath» debajo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'e56520e7-d823-47f5-8172-6069d362e58a', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '4b4802ff-b963-4355-8c48-4f87708d742d', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (35)?',
  array['once', 'worst', 'last', 'all'],
  'Vuelve a la lista de expresiones con «at» y escoge la que hable de cantidad de una sola vez.', 'publicada', 'modelo', 'b4409f5314d9cb3d69ae44d658e0b959';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('e56520e7-d823-47f5-8172-6069d362e58a', 0, '«At once» significa de una sola vez, y el consejo es no comer muchos ajíes de golpe. «At last» es por fin, «at all» en absoluto, y «at worst» no encaja con la advertencia.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'aa3ab025-1a92-4c02-a01c-43c398477a18', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '6e9d8b5f-ef4d-464a-9af2-e295fb1a94af', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (16)?',
  array['shall', 'must', 'could'],
  'Must marca lo que no se puede evitar; could, lo que se puede elegir. Fíjate en cuál pide la situación.', 'publicada', 'modelo', '6c045ed25f85ba849f57fbbde0a87a54';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('aa3ab025-1a92-4c02-a01c-43c398477a18', 1, 'Ser padre soltero de dos adolescentes trae consigo una obligación: le toca cuidarlos. «Must» expresa ese deber. «Could» hablaría de una posibilidad y «shall» de una propuesta, y ninguna encaja con una responsabilidad familiar.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c85c70d2-a833-40e2-8478-8d78c52d9f39', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '6e9d8b5f-ef4d-464a-9af2-e295fb1a94af', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (17)?',
  array['take', 'taking', 'taken'],
  'Cuidado con este «to»: en «when it comes to» es preposición, no marca de infinitivo.', 'publicada', 'modelo', 'ce6fdeb390778f108308aabff2600e73';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c85c70d2-a833-40e2-8478-8d78c52d9f39', 1, 'La expresión «when it comes to» termina en una preposición, así que el verbo que sigue va en gerundio. Es la misma regla de siempre: tras preposición, -ing.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '32ef5187-1af0-4fae-a1df-ce8408bc7a69', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '6e9d8b5f-ef4d-464a-9af2-e295fb1a94af', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (18)?',
  array['met', 'meet', 'meeting'],
  'Si el hueco está al principio y le sigue un verbo conjugado, lo que falta es un sujeto: gerundio.', 'publicada', 'modelo', 'b8909dccc5bce24600c1a95b43bfbfa9';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('32ef5187-1af0-4fae-a1df-ce8408bc7a69', 2, 'El hueco abre la frase y funciona como sujeto de «is important», así que necesita la forma en -ing, que actúa como sustantivo. Un pasado o un infinitivo suelto no pueden ser sujeto aquí.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '0fce90db-f47e-4d43-ba1d-44ac9b03fed6', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '6e9d8b5f-ef4d-464a-9af2-e295fb1a94af', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (19)?',
  array['more', 'most', 'much'],
  'The + most + adjetivo = superlativo. La presencia de «the» es la señal.', 'publicada', 'modelo', '361ff149e2c29a9e43b0b217dcc85b88';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('0fce90db-f47e-4d43-ba1d-44ac9b03fed6', 1, 'El artículo «the» delante y la ausencia de «than» señalan un superlativo: la cosa más importante de la lista. «More» compararía dos y «much» acompaña a incontables.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '1324cbf2-99cc-4f1d-8cdd-c5cd2f6453e0', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '6e9d8b5f-ef4d-464a-9af2-e295fb1a94af', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (20)?',
  array['go', 'went', 'gone'],
  'La palabra «ago» siempre arrastra pasado simple. Es una señal infalible.', 'publicada', 'modelo', '97066d680f8ed9af341010507c803456';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('1324cbf2-99cc-4f1d-8cdd-c5cd2f6453e0', 1, '«Two months ago» sitúa la acción en el pasado y el verbo va solo, sin auxiliar, así que corresponde el pasado simple. «Gone» pediría have delante.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'bd3d4973-807e-4b32-8abb-04e1c3eba801', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '6e9d8b5f-ef4d-464a-9af2-e295fb1a94af', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (21)?',
  array['interested', 'interest', 'interesting'],
  'Regla de oro: -ing describe la cosa que causa la emoción; -ed, a la persona que la siente.', 'publicada', 'modelo', '379f3e9b9b96679efab71bf020cf5ad8';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('bd3d4973-807e-4b32-8abb-04e1c3eba801', 2, 'Lo que se describe es el celular, no una persona, y los objetos que despiertan interés son «interesting». La forma en -ed describiría a quien siente el interés.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '7c1a6f8c-d6ac-4930-a752-0ebb1c207ed6', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '6e9d8b5f-ef4d-464a-9af2-e295fb1a94af', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (22)?',
  array['at', 'into', 'on'],
  'Ordena las tres por tamaño: at para la hora, on para el día, in para el mes o el año.', 'publicada', 'modelo', '06e73fe691259959032322f4ef83b923';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('7c1a6f8c-d6ac-4930-a752-0ebb1c207ed6', 0, 'Las horas exactas llevan «at»: at 5 o&rsquo;clock. «On» se usa con días y fechas, e «into» indica movimiento hacia dentro.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c48f5723-d5b5-42cd-8ed9-4ce8bed8a8e8', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  '6e9d8b5f-ef4d-464a-9af2-e295fb1a94af', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (23)?',
  array['quite', 'also', 'once'],
  'Cuando la frase agrega un uso más a los ya mencionados, el adverbio es also.', 'publicada', 'modelo', '7bd5f2c0ceba8c13e86fce9848014d94';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c48f5723-d5b5-42cd-8ed9-4ce8bed8a8e8', 1, 'El párrafo va sumando funciones del celular: despertador y, además, consultar internet y enviar mensajes. Esa adición la marca «also». «Quite» gradúa un adjetivo y «once» habla de una sola vez.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'a85afcac-ca5a-41af-847b-86ac59033757', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (31)?',
  array['carry', 'deliver', 'bring', 'take'],
  'Take… for a walk se aprende de bloque. Take se aleja del hablante; bring se acerca.', 'publicada', 'modelo', '4f9e1edd51b11604d98a84b8e9cb4ad7';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('a85afcac-ca5a-41af-847b-86ac59033757', 3, 'Sacar al perro a pasear es «take your dog for a walk», una expresión fija. «Carry» es cargarlo en brazos, «deliver» entregarlo y «bring» traerlo hacia quien habla.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'c17d4480-4f2d-42ba-8132-e812dcf125f9', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (32)?',
  array['admit', 'allow', 'accept', 'agree'],
  'Comprueba la construcción que pide cada verbo: allow somebody to do something es la que encaja aquí.', 'publicada', 'modelo', '349841037ddb9dd4f985f641fc8da6c5';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('c17d4480-4f2d-42ba-8132-e812dcf125f9', 1, 'La estructura «allow + objeto + to + verbo» es la única de las cuatro que admite esa construcción con ese sentido de permitir. Aquí se aconseja no dejar que el perro huela todo.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '717d09cb-6f02-47e3-b322-ba976cd69d85', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (33)?',
  array['then', 'hence', 'also', 'indeed'],
  'La expresión «In addition to…» al inicio ya anuncia que se va a sumar algo: el adverbio debe acompañar esa suma.', 'publicada', 'modelo', 'c243b7b2074fab9875cb153499e1b26f';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('717d09cb-6f02-47e3-b322-ba976cd69d85', 2, 'Se añade un beneficio más del paseo, junto al entrenamiento y la jerarquía que ya se mencionaron. «Then» ordena en el tiempo, «hence» introduce consecuencia y «indeed» refuerza algo ya dicho.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '5bf21e17-d773-411f-999e-30c94952324b', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (34)?',
  array['making', 'producing', 'doing', 'developing'],
  'Do y make se reparten los sustantivos y hay que memorizarlos: do exercise, do homework, make a decision.', 'publicada', 'modelo', '475c979ccba96c4e260ec0cb079d56a1';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('5bf21e17-d773-411f-999e-30c94952324b', 2, 'Hacer ejercicio en inglés es «do exercise». Los otros tres verbos se combinan con otros objetos: make a decision, produce goods, develop a skill.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '9a897702-ab70-460e-aa96-4b34a23a8aff', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (35)?',
  array['realizes', 'dreams', 'imagines', 'examines'],
  'Realize no es «realizar»: significa darse cuenta. Es uno de los falsos amigos que más caen en el examen.', 'publicada', 'modelo', '8628fd829354dae02654661d922e0ba2';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('9a897702-ab70-460e-aa96-4b34a23a8aff', 0, 'El perro se da cuenta de quién manda, y darse cuenta de algo es «realize». Soñar, imaginar y examinar no describen esa comprensión de una situación real.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'b8644375-749f-4b56-ac08-c9722c51749f', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (36)?',
  array['wishes', 'opinions', 'requirements', 'instructions'],
  'Piensa qué puede atender realmente un animal: órdenes concretas, no ideas abstractas.', 'publicada', 'modelo', 'dcaafefbae01d014559152230d9365bf';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('b8644375-749f-4b56-ac08-c9722c51749f', 3, 'Durante el paseo el perro debe concentrarse en lo que su dueño le indica, y esas indicaciones son instrucciones. Deseos, opiniones y requisitos no son cosas que un perro pueda seguir.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '897a24a7-f10f-4466-8e2f-f8b524d5fe08', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (37)?',
  array['better', 'well', 'best', 'good'],
  'The + superlativo es la pareja fija. Si además no hay than, se confirma.', 'publicada', 'modelo', '06d1c87447b1ee9f3513f3196b2b7254';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('897a24a7-f10f-4466-8e2f-f8b524d5fe08', 2, 'El artículo «the» delante del hueco pide un superlativo, y no hay ningún «than» que sugiera comparación. «Well» es adverbio y no puede acompañar a un sustantivo como behavior.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select 'd3ebc7b1-d794-474d-9a25-306c0949a291', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (38)?',
  array['by', 'on', 'for', 'at'],
  'On my own, on your own, on its own: la expresión lleva siempre el posesivo, no el reflexivo.', 'publicada', 'modelo', '19671144fdcaa1c45ed35c00b5e37c78';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('d3ebc7b1-d794-474d-9a25-306c0949a291', 1, '«On its own» significa por su cuenta, solo, y es la expresión que corresponde a un perro dejado sin supervisión. «By itself» diría algo parecido, pero con el pronombre reflexivo, no con «its».');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '337814cf-97ad-48cd-b743-ae511f0e5c21', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (39)?',
  array['rises', 'grows', 'raises', 'increases'],
  'Distingue raise (necesita objeto) de rise e increase (van solos). El primero siempre lleva algo detrás.', 'publicada', 'modelo', '5f0570ac07eb02ed149b4431fee76511';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('337814cf-97ad-48cd-b743-ae511f0e5c21', 3, 'La posibilidad de meterse en problemas aumenta, y con sustantivos abstractos como possibility la colocación habitual es «increases». «Raises» es transitivo y exigiría un objeto detrás, que aquí no hay.');

insert into public.preguntas (id, materia, tema_id, lote_id, contexto_id, comp, enunciado, opciones, tip, estado, clave_origen, hash_norm)
select '52c10f62-64ef-4217-9b7f-051556c4d694', 'ing',
  (select id from public.temas where materia = 'ing' and codigo = 'parte-5-completar'),
  (select id from public.lotes where codigo = '2026-B'),
  'a63af53e-30da-430b-a1a8-13656811c392', 'Parte 4 · Completar texto',
  '¿Qué palabra va en el espacio (40)?',
  array['suitable', 'sure', 'smart', 'straight'],
  'Suitable equivale a apropiado o adecuado. Aparece siempre acompañando planes, rutinas y horarios.', 'publicada', 'modelo', 'd95092cb68ba61411996004e0c91bb17';
insert into public.preguntas_clave (pregunta_id, correcta, explicacion) values ('52c10f62-64ef-4217-9b7f-051556c4d694', 0, 'Todo el texto propone una rutina hecha a la medida del perro, es decir, adecuada. «Sure» significa seguro de algo, «smart» inteligente y «straight» recto, y ninguno califica una rutina de ejercicio.');

